  // 두벌식에서 ㅡ(M) 대신 바로 오른쪽 쉼표(,)를 눌러
  // '초성,종성'으로 풀린 입력을 초성+ㅡ+종성 완성 음절로 복원한다.
  const CHOSEONG_INDEX = Object.freeze({
    'ㄱ': 0, 'ㄲ': 1, 'ㄴ': 2, 'ㄷ': 3, 'ㄸ': 4, 'ㄹ': 5, 'ㅁ': 6,
    'ㅂ': 7, 'ㅃ': 8, 'ㅅ': 9, 'ㅆ': 10, 'ㅇ': 11, 'ㅈ': 12, 'ㅉ': 13,
    'ㅊ': 14, 'ㅋ': 15, 'ㅌ': 16, 'ㅍ': 17, 'ㅎ': 18
  });
  const JONGSEONG_INDEX = Object.freeze({
    'ㄱ': 1, 'ㄲ': 2, 'ㄳ': 3, 'ㄴ': 4, 'ㄵ': 5, 'ㄶ': 6, 'ㄷ': 7,
    'ㄹ': 8, 'ㄺ': 9, 'ㄻ': 10, 'ㄼ': 11, 'ㄽ': 12, 'ㄾ': 13, 'ㄿ': 14,
    'ㅀ': 15, 'ㅁ': 16, 'ㅂ': 17, 'ㅄ': 18, 'ㅅ': 19, 'ㅆ': 20, 'ㅇ': 21,
    'ㅈ': 22, 'ㅊ': 23, 'ㅋ': 24, 'ㅌ': 25, 'ㅍ': 26, 'ㅎ': 27
  });

  function composeEuSyllable(initial, final) {
    const choseong = CHOSEONG_INDEX[initial];
    const jongseong = JONGSEONG_INDEX[final];
    if (!Number.isInteger(choseong) || !Number.isInteger(jongseong)) return `${initial},${final}`;
    const JUNGSEONG_EU_INDEX = 18;
    return String.fromCharCode(0xAC00 + ((choseong * 21 + JUNGSEONG_EU_INDEX) * 28) + jongseong);
  }


  function composeISyllable(initial, final) {
    const choseong = CHOSEONG_INDEX[initial];
    const jongseong = JONGSEONG_INDEX[final];
    if (!Number.isInteger(choseong) || !Number.isInteger(jongseong)) return `${initial};${final}`;
    const JUNGSEONG_I_INDEX = 20;
    return String.fromCharCode(0xAC00 + ((choseong * 21 + JUNGSEONG_I_INDEX) * 28) + jongseong);
  }

  function composeESyllable(initial, final, separator = '[') {
    const choseong = CHOSEONG_INDEX[initial];
    const jongseong = JONGSEONG_INDEX[final];
    if (!Number.isInteger(choseong) || !Number.isInteger(jongseong)) return `${initial}${separator}${final}`;
    const JUNGSEONG_E_INDEX = 5;
    return String.fromCharCode(0xAC00 + ((choseong * 21 + JUNGSEONG_E_INDEX) * 28) + jongseong);
  }

