    '얼굴': ['얼국', '얼굿', '얼궁', '얼궇'],
    '입술': ['입숙', '입숫', '입숭', '입숳'],
    '손목': ['손몯', '손못', '손몽', '손몰'],
    '심장': ['심잗', '심작', '심잔', '심잘'],
    '체온': ['체옺', '체옫', '체옴', '체옹'],
    '행동': ['행돋', '행독', '행돈', '행돌'],
