    '위험': ['위헙', '위헞'],
    '의심': ['의십', '의싲'],
    '믿음': ['믿읍', '믿읒'],
    '배신': ['배싲', '배싣', '배싱'],
    '부탁': ['부탇', '부탓', '부탈'],
    '질문': ['질뭊', '질묻', '질뭄', '질뭉'],
    '현실': ['현싯', '현싱', '현싷'],
    '운명': ['운멷', '운멱', '운면', '운멸'],
    '가족': ['가졷', '가좃', '가졸'],
    '연인': ['연잊', '연읻', '연잉'],
    '계단': ['계닺', '계닫', '계당'],
    '정원': ['정웢', '정웓', '정웜', '정웡'],
    '궁전': ['궁젖', '궁젇', '궁점'],
    '새벽': ['새볃', '새볏'],
    '아침': ['아칩', '아칮'],
    '저녁': ['저녇', '저녓', '저녕', '저녈'],
    '겨울': ['겨욱', '겨웃', '겨웅', '겨웋'],
    '여름': ['여릅', '여릊'],
    '가을': ['가윽', '가읏', '가응', '가읗']
